/**
 * The treatment evidence for the colorectal cancer deep dive: adjuvant chemotherapy, rectal cancer surgery and
 * radiotherapy, the biological agents by RAS status and sidedness, immunotherapy for mismatch repair-deficient
 * disease, the BRAF, HER2 and KRAS G12C trials, the circulating tumour DNA trials, peritoneal disease and the one
 * supportive-care trial with a survival endpoint. Metadata verbatim from Europe PMC, read 2026-09-24; figures only
 * from the indexed abstracts.
 */
type P = Omit<PaperInput, "kind" | "asOf">;
const p = (x: P): PaperInput => ({ kind: "paper", asOf, tags: ["colorectal-evidence"], ...x });

